SELECT TO_CHAR(s.recorded_at, 'YYYY-MM-DD') AS day, COUNT(*) FROM market_snapshots s JOIN (SELECT DISTINCT market_id, TO_CHAR(created_at, 'YYYY-MM-DD') AS fday FROM decision_funnel_log WHERE created_at >= TIMESTAMPTZ '2026-08-03 00:00:00+00' AND created_at < TIMESTAMPTZ '2026-09-14 00:00:00+00') dm ON dm.market_id = s.market_id AND dm.fday = TO_CHAR(s.recorded_at, 'YYYY-MM-DD') WHERE s.recorded_at >= TIMESTAMPTZ '2026-08-03 00:00:00+00' AND s.recorded_at < TIMESTAMPTZ '2026-09-14 00:00:00+00' GROUP BY 1 ORDER BY 1;
